#Requires -Modules @{ ModuleName = 'Pester'; RequiredVersion = '5.7.1' }

BeforeAll {
    $script:ScriptPath = Join-Path $PSScriptRoot '..\Remove-CommitAttribution.ps1'
    . $script:ScriptPath -RepoRoot $TestDrive

    $script:DefaultPattern = @(
        '^\s*co-authored-by:',
        '^\s*generated (by|with) .*\b(copilot|claude|codex|chatgpt|gemini|cursor)\b'
    )

    function Invoke-TestGit {
        $Output = & git @args 2>&1
        if ($LASTEXITCODE -ne 0) {
            throw "git $($args -join ' ') failed: $Output"
        }
        return $Output
    }

    function New-TestRepository {
        param(
            [Parameter(Mandatory = $true)]
            [string]$Name
        )

        $Remote = Join-Path $TestDrive "$Name-remote.git"
        $Work = Join-Path $TestDrive $Name
        Invoke-TestGit init --quiet --bare --initial-branch=main $Remote | Out-Null
        Invoke-TestGit init --quiet --initial-branch=main $Work | Out-Null
        Invoke-TestGit -C $Work config user.name 'Example Author' | Out-Null
        Invoke-TestGit -C $Work config user.email 'author@example.com' | Out-Null
        Invoke-TestGit -C $Work config commit.gpgsign false | Out-Null
        Invoke-TestGit -C $Work remote add origin $Remote | Out-Null
        Add-TestCommit -Repository $Work -File 'base.txt' -Message "chore: base`n`nCo-authored-by: Copilot <copilot@example.com>"
        Invoke-TestGit -C $Work push --quiet -u origin main | Out-Null
        Invoke-TestGit -C $Work remote set-head origin main | Out-Null
        Invoke-TestGit -C $Work switch --quiet -c feature | Out-Null
        return $Work
    }

    function Add-TestCommit {
        param(
            [Parameter(Mandatory = $true)]
            [string]$Repository,

            [Parameter(Mandatory = $true)]
            [string]$File,

            [Parameter(Mandatory = $true)]
            [string]$Message,

            [Parameter(Mandatory = $false)]
            [string]$Date = '2026-01-02T03:04:05+01:00'
        )

        Set-Content -LiteralPath (Join-Path $Repository $File) -Value $File
        Invoke-TestGit -C $Repository add $File | Out-Null
        $env:GIT_AUTHOR_DATE = $Date
        $env:GIT_COMMITTER_DATE = '2026-02-03T04:05:06-05:00'
        try {
            Invoke-TestGit -C $Repository commit --quiet --cleanup=verbatim -m $Message | Out-Null
        }
        finally {
            Remove-Item Env:GIT_AUTHOR_DATE, Env:GIT_COMMITTER_DATE
        }
    }

    function Get-TestMessage {
        param(
            [Parameter(Mandatory = $true)]
            [string]$Repository,

            [Parameter(Mandatory = $true)]
            [string]$Revision
        )

        return ((Invoke-TestGit -C $Repository log -1 --format=%B $Revision) -join "`n").TrimEnd()
    }
}

Describe 'Remove-AttributionLine' -Tag 'Unit' {
    It 'Removes agent lines, keeps other trailers and trims trailing blank lines' {
        $Message = "feat: add thing`n`n- detail`n`nSigned-off-by: Example <a@example.com>`nCo-authored-by: Copilot <c@example.com>`nco-authored-by: Bot <b@example.com>`n`n"

        $Result = Remove-AttributionLine -Message $Message -LinePattern $script:DefaultPattern

        $Result.Removed | Should -Be 2
        $Result.Message | Should -Be "feat: add thing`n`n- detail`n`nSigned-off-by: Example <a@example.com>`n"
    }

    It 'Returns the message unchanged when nothing matches' {
        $Message = "fix: thing`n`nGenerated by a build script`n"

        $Result = Remove-AttributionLine -Message $Message -LinePattern $script:DefaultPattern

        $Result.Removed | Should -Be 0
        $Result.Message | Should -BeExactly $Message
    }
}

Describe 'Invoke-CommitAttributionRemoval' -Tag 'Unit' {
    It 'Rewrites only unpushed commits and preserves trees, identities, dates and the working tree' {
        $Repo = New-TestRepository -Name 'rewrite'
        Add-TestCommit -Repository $Repo -File 'one.txt' -Message "feat: one`n`nCo-authored-by: Copilot <copilot@example.com>"
        Add-TestCommit -Repository $Repo -File 'two.txt' -Message 'feat: two' -Date '2026-03-04T05:06:07+02:00'
        Set-Content -LiteralPath (Join-Path $Repo 'untracked.txt') -Value 'keep'
        $OldTip = (Invoke-TestGit -C $Repo rev-parse HEAD).Trim()
        $OldMeta = Invoke-TestGit -C $Repo log --format='%T|%an|%ae|%aI|%cn|%ce|%cI' main..HEAD
        $PushedTip = (Invoke-TestGit -C $Repo rev-parse origin/main).Trim()

        $Result = Invoke-CommitAttributionRemoval -RepoRoot $Repo -LinePattern $script:DefaultPattern -SkipFetch

        $Result.RewrittenCommits | Should -Be 2
        $Result.RemovedLines | Should -Be 1
        (Invoke-TestGit -C $Repo rev-parse HEAD).Trim() | Should -Be $Result.NewTip
        (Invoke-TestGit -C $Repo rev-parse $Result.BackupRef).Trim() | Should -Be $OldTip
        Invoke-TestGit -C $Repo log --format='%T|%an|%ae|%aI|%cn|%ce|%cI' main..HEAD | Should -Be $OldMeta
        Get-TestMessage -Repository $Repo -Revision 'HEAD~1' | Should -Be 'feat: one'
        (Invoke-TestGit -C $Repo rev-parse main).Trim() | Should -Be $PushedTip
        Get-TestMessage -Repository $Repo -Revision 'main' | Should -Match 'Co-authored-by'
        Get-Content -LiteralPath (Join-Path $Repo 'untracked.txt') | Should -Be 'keep'
        Invoke-TestGit -C $Repo status --porcelain | Should -Be '?? untracked.txt'
    }

    It 'Preserves merge topology' {
        $Repo = New-TestRepository -Name 'merge'
        Invoke-TestGit -C $Repo switch --quiet -c side | Out-Null
        Add-TestCommit -Repository $Repo -File 'side.txt' -Message "feat: side`n`nCo-authored-by: Copilot <copilot@example.com>"
        Invoke-TestGit -C $Repo switch --quiet feature | Out-Null
        Add-TestCommit -Repository $Repo -File 'main.txt' -Message 'feat: main line'
        Invoke-TestGit -C $Repo merge --quiet --no-ff --no-edit side | Out-Null
        $OldTree = (Invoke-TestGit -C $Repo rev-parse 'HEAD^{tree}').Trim()

        $Result = Invoke-CommitAttributionRemoval -RepoRoot $Repo -LinePattern $script:DefaultPattern -SkipFetch

        $Result.RewrittenCommits | Should -Be 2
        @((Invoke-TestGit -C $Repo log -1 --format=%P HEAD) -split ' ').Count | Should -Be 2
        (Invoke-TestGit -C $Repo rev-parse 'HEAD^{tree}').Trim() | Should -Be $OldTree
        Get-TestMessage -Repository $Repo -Revision 'HEAD^2' | Should -Be 'feat: side'
    }

    It 'Makes no change when no unpushed commit carries attribution' {
        $Repo = New-TestRepository -Name 'clean'
        Add-TestCommit -Repository $Repo -File 'one.txt' -Message 'feat: one'
        $OldTip = (Invoke-TestGit -C $Repo rev-parse HEAD).Trim()

        $Result = Invoke-CommitAttributionRemoval -RepoRoot $Repo -LinePattern $script:DefaultPattern -SkipFetch

        $Result.RewrittenCommits | Should -Be 0
        $Result.BackupRef | Should -BeNullOrEmpty
        (Invoke-TestGit -C $Repo rev-parse HEAD).Trim() | Should -Be $OldTip
    }

    It 'Reports without rewriting under -WhatIf' {
        $Repo = New-TestRepository -Name 'whatif'
        Add-TestCommit -Repository $Repo -File 'one.txt' -Message "feat: one`n`nCo-authored-by: Copilot <copilot@example.com>"
        $OldTip = (Invoke-TestGit -C $Repo rev-parse HEAD).Trim()

        $Result = Invoke-CommitAttributionRemoval -RepoRoot $Repo -LinePattern $script:DefaultPattern -SkipFetch -WhatIf

        $Result.RemovedLines | Should -Be 1
        $Result.RewrittenCommits | Should -Be 0
        (Invoke-TestGit -C $Repo rev-parse HEAD).Trim() | Should -Be $OldTip
        Invoke-TestGit -C $Repo for-each-ref refs/attribution-backup | Should -BeNullOrEmpty
    }

    It 'Refuses the default branch' {
        $Repo = New-TestRepository -Name 'default'
        Invoke-TestGit -C $Repo switch --quiet main | Out-Null

        { Invoke-CommitAttributionRemoval -RepoRoot $Repo -LinePattern $script:DefaultPattern -SkipFetch } |
            Should -Throw '*default branch*'
    }

    It 'Refuses a signed commit and leaves the branch unchanged' {
        $Repo = New-TestRepository -Name 'signed'
        $Parent = (Invoke-TestGit -C $Repo rev-parse HEAD).Trim()
        $Tree = (Invoke-TestGit -C $Repo rev-parse 'HEAD^{tree}').Trim()
        $Object = "tree $Tree`nparent $Parent`nauthor Example Author <author@example.com> 1767225600 +0000`ncommitter Example Author <author@example.com> 1767225600 +0000`ngpgsig -----BEGIN PGP SIGNATURE-----`n synthetic`n -----END PGP SIGNATURE-----`n`nfeat: signed`n`nCo-authored-by: Copilot <copilot@example.com>`n"
        $ObjectPath = Join-Path $TestDrive 'signed-commit.txt'
        [IO.File]::WriteAllText($ObjectPath, $Object)
        $Signed = (Invoke-TestGit -C $Repo hash-object -t commit -w $ObjectPath).Trim()
        Invoke-TestGit -C $Repo update-ref refs/heads/feature $Signed | Out-Null

        { Invoke-CommitAttributionRemoval -RepoRoot $Repo -LinePattern $script:DefaultPattern -SkipFetch } |
            Should -Throw '*gpgsig*'
        (Invoke-TestGit -C $Repo rev-parse HEAD).Trim() | Should -Be $Signed
    }
}
